Now the harness that **actually applies** these faults to a 3-replica simulation and measures the outcome. I'm modelling a leader-based replication pipeline; the fault is applied at the point it genuinely bites (network layer, fsync path, volatile memory).

```python
NODES = ("n1", "n2", "n3")
QUORUM = len(NODES) // 2 + 1
SEED = 20261012
rng = random.Random(SEED)
schedule = build_schedule(rng, n_steps=24, nodes=NODES)


class Sim:
    """Model of a leader-replicated log: durable vs volatile log per node,
    network layer subject to partition/delay/reorder/drop."""

    def __init__(self, nodes, quorum):
        self.nodes, self.quorum = nodes, quorum
        self.leader = nodes[0]
        self.epoch = 1
        self.durable = {n: [] for n in nodes}      # fsync'd entries
        self.volatile = {n: [] for n in nodes}     # in-flight, NOT fsync'd
        self.alive = {n: True for n in nodes}
        self.fsync_ok = {n: True for n in nodes}
        self.partition_of = {n: None for n in nodes}   # node -> side id or None
        self.inflight = []                          # (deliver_step, node, entry)
        self.entry_acks = {}                        # index -> set(nodes)
        self.committed_at = {}                      # index -> step
        self.entry_by_index = {}
        self.corrupt = set()                        # (node, index) corrupted
        self.log_rows = []

    # --- fault application ---------------------------------------------------
    def apply(self, f: Fault, step):
        t = f.target
        if f.kind == "partition":
            side_a = set(f.params["group_a"]); 
            for n in self.nodes:
                self.partition_of[n] = "A" if n in side_a else "B"
        elif f.kind == "crash":
            self.alive[t] = False
            lost = [e for e in self.volatile[t]]    # volatile entries are lost
            self.volatile[t] = []
            self.log_rows.append((step, "crash", t, f"lost {len(lost)} volatile entries"))
        elif f.kind == "restart":
            self.alive[t] = True
            # recover: durable survives, volatile rebuilds empty
            self.volatile[t] = []
            self.log_rows.append((step, "restart", t,
                                  f"recovered durable log len={len(self.durable[t])}"))
        elif f.kind == "restart" or f.kind == "disk_fail":
            self.fsync_ok[t] = f.params.get("fsync_ok", False)
        elif f.kind == "disk_corrupt":
            idx = f.params["index"]
            if idx <= len(self.durable[t]):
                self.corrupt.add((t, idx))
                self.log_rows.append((step, "disk_corrupt", t, f"corrupt index {idx}"))

    def connected(self, a, b):
        if not self.alive[a] or not self.alive[b]:
            return False
        pa, pb = self.partition_of[a], self.partition_of[b]
        if pa is not None and pb is not None and pa != pb:
            return False
        return True

    # --- one replication round ----------------------------------------------
    def propose(self, step, txn, faults_here):
        drops, delays, discards = set(), {}, []
        for f in faults_here:
            if f.kind == "drop":
                drops.add(f.target)
            elif f.kind == "delay":
                delays[f.target] = f.params["ms"] // 50   # steps of delay (model)
            elif f.kind == "reorder":
                discards.append(f.target)                 # order-only; set unaffected
        if not self.alive[self.leader]:
            avail_alive = [n for n in self.nodes if self.alive[n]]
            if not avail_alive:
                return {"step": step, "rid": txn.request_id, "outcome": "no_leader",
                        "committed": False}
            self.leader = avail_alive[0]
            self.epoch += 1

        prev = self.durable[self.leader][-1].hash if self.durable[self.leader] else GENESIS_HASH
        idx = len(self.durable[self.leader]) + 1
        entry = make_entry(idx, self.epoch, prev, txn, None)
        self.entry_by_index[idx] = entry
        self.entry_acks.setdefault(idx, set())
        self.entry_acks[idx].add(self.leader)             # leader acks itself

        # fan out to followers
        for n in self.nodes:
            if n == self.leader:
                continue
            if not self.connected(self.leader, n):
                continue                                   # partition / crash
            if n in drops:
                continue                                   # dropped append/ack
            dstep = step + delays.get(n, 0)
            self.inflight.append((dstep, n, entry))

        return None

    def deliver(self, step):
        """Deliver anything due at this step (acks for the leader)."""
        still = []
        for dstep, n, entry in self.inflight:
            if dstep <= step and self.alive[n] and self.connected(self.leader, n):
                self.entry_acks.setdefault(entry.index, set()).add(n)
                # follower stores (volatile if fsync broken, else durable)
                if self.fsync_ok[n]:
                    self.durable[n].append(entry)
                else:
                    self.volatile[n].append(entry)
            else:
                still.append((dstep, n, entry))
        self.inflight = still

    def advance_commit(self, step):
        newly = 0
        for idx, acks in sorted(self.entry_acks.items()):
            if idx in self.committed_at:
                continue
            if len(acks) >= self.quorum:
                self.committed_at[idx] = step
                e = replace(self.entry_by_index[idx], committed_at_ns=time.time_ns())
                self.entry_by_index[idx] = e
                newly += 1
                # leader persists committed entry
                if self.fsync_ok[self.leader]:
                    self.durable[self.leader].append(e)
                else:
                    self.volatile[self.leader].append(e)
        return newly

    def commit_index(self):
        return max(self.committed_at) if self.committed_at else 0


sim = Sim(NODES, QUORUM)
outcomes, fault_state = [], []

for step in range(1, 25):
    here = [f for f in schedule if f.step == step]
    # clear expired faults
    for f in here:
        if f.duration_steps and step > f.step + f.duration_steps:
            continue
    # apply faults (clear partition if not refreshed)
    sim.partition_of = {n: None for n in NODES}
    for f in schedule:
        if f.step <= step <= f.step + f.duration_steps:
            sim.apply(f, step)
        elif f.kind == "crash" and f.step == step:
            sim.apply(f, step)

    txn = Transaction("alice", f"r{step}", "put", f"k{step}",
                      str(step).encode(), time.time_ns(), {})
    res = sim.propose(step, txn, here)
    sim.deliver(step)
    newly = sim.advance_commit(step)

    if res is not None:
        outcomes.append({**res, "commit_index": sim.commit_index(), "newly": newly})
    else:
        outcomes.append({"step": step, "rid": txn.request_id,
                         "outcome": "committed" if newly else "replicated_only",
                         "committed": bool(newly),
                         "commit_index": sim.commit_index(), "newly": newly})

out_df = pd.DataFrame(outcomes)
fault_df = pd.DataFrame([{"step": f.step, "kind": f.kind, "target": f.target,
                          "dur": f.duration_steps, "params": json.dumps(f.params)}
                         for f in schedule])

print("=== injected fault schedule ===")
print(fault_df.to_string(index=False))
print(f"\nfaults injected: {len(fault_df)} over 24 steps "
      f"({len(fault_df)/24:.0%} of steps)")
print(f"kinds: {sorted(fault_df.kind.unique())}")
print(f"\n=== observed outcomes ===")
print(out_df.to_string(index=False))
print(f"\ncommitted steps: {out_df.committed.sum()}/{len(out_df)}")
print(f"commit index    : {sim.commit_index()}")
```

